"""
    Create a method named "rotate" that returns a given array with the elements
    inside the array rotated n spaces.
    with array [1, 2, 3, 4, 5]
    n = 7        =>    [4, 5, 1, 2, 3]
    n = 11       =>    [5, 1, 2, 3, 4]
    n = -3       =>    [4, 5, 1, 2, 3]
    """
def rotate(data: Any, n: Any) -> object {
    if data {
        k = len(data);
        n = n % k;
        return (data[(k - n):] + data[:(k - n)]);
    }
    return data;
}

"""Prevent parsing errors by converting <, >, & to their HTML codes."""
def sanitize_html(text: Any) -> object {
    return text.replace('<', '&lt;').replace('>', '&gt;').replace('&', '&amp;');
}

""" Returns value what_ from_ """
def config_get(from_: Any, what_: Any) -> object {
    from_ = from_.replace(' ', '');
    d = from_[(from_.index((what_ + '=')) + 1 + len(what_)):].split('\n')[0];
    return d;
}

"""
    Checks whether a port update is being called for a port status change
    event.

    Port activation events are triggered by our own action: if the only change
    in the port dictionary is activation state, we don't want to do any
    processing.
    """
def port_status_change(port: Any, original: Any) -> object {
    port = port.copy();
    original = original.copy();
    port.pop('status');
    original.pop('status');
    if (port == original) {
        return True;
    } else {
        return False;
    }
}
